// Extract relevant fields from Evolution API webhook payload
const body = $input.item.json.body;
const message = body?.data?.message?.conversation || body?.data?.message?.extendedTextMessage?.text || '';
const phoneRaw = body?.data?.key?.remoteJid || '';
// remoteJid format: 51XXXXXXXXX@s.whatsapp.net
const phone = phoneRaw.split('@')[0];
const isFromMe = body?.data?.key?.fromMe || false;
const messageType = body?.event || 'unknown';

if (isFromMe || !phone || !message) {
  return [{ json: { skip: true } }];
}

return [{ json: { phone, message, messageType, rawBody: body } }];

// Determine new estado_contacto based on current stage
const lead = $input.item.json;
const currentEstado = lead?.estado_contacto || '';
const autoStatus = lead?.automation_status || 'idle';
const sentAt = lead?.enviado_at ? new Date(lead.enviado_at) : null;
const now = new Date();

// Calculate response time in minutes
let responseTimeMinutes = null;
if (sentAt) {
  responseTimeMinutes = Math.round((now - sentAt) / (1000 * 60));
}

// Determine what stage they responded to
let newEstado = currentEstado;
if (currentEstado.includes('Apertura') || currentEstado === 'Pendiente') {
  newEstado = 'Respondió Apertura';
} else if (currentEstado.includes('Activador')) {
  newEstado = 'Respondió Activador';
} else if (currentEstado.includes('Video')) {
  newEstado = 'Respondió Video';
} else if (currentEstado.includes('Cierre')) {
  newEstado = 'Respondió Cierre';
}

// Auto-Kill: if lead was queued or staged, cancel future messages
const shouldCancelQueue = autoStatus === 'queued' || autoStatus === 'staged';

return [{
  json: {
    lead_id: lead.id,
    newEstado,
    responseTimeMinutes,
    shouldCancelQueue,
    incomingMessage: $('Extraer Mensaje').item.json.message
  }
}];
